ALTER TABLE account_users ADD COLUMN is_organizer INTEGER NOT NULL DEFAULT 0 CHECK(is_organizer IN (0,1));
CREATE TABLE event_competitions (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',grade_label TEXT NOT NULL DEFAULT '',venue TEXT NOT NULL DEFAULT '',starts_at TEXT NOT NULL DEFAULT '',min_students INTEGER NOT NULL DEFAULT 1 CHECK(min_students BETWEEN 1 AND 20),max_students INTEGER NOT NULL DEFAULT 1 CHECK(max_students BETWEEN 1 AND 20 AND max_students>=min_students),registration_open INTEGER NOT NULL DEFAULT 1 CHECK(registration_open IN (0,1)),created_by TEXT NOT NULL REFERENCES account_users(id),created_at INTEGER NOT NULL);
CREATE TABLE registration_documents (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES account_users(id),content_type TEXT NOT NULL CHECK(content_type IN ('image/jpeg','image/png')),size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 1048576),data BLOB NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX registration_documents_owner ON registration_documents(owner_id,created_at);
CREATE TABLE event_registrations (id TEXT PRIMARY KEY,competition_id TEXT NOT NULL REFERENCES event_competitions(id),owner_id TEXT NOT NULL REFERENCES account_users(id),request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','changes_requested')),revision INTEGER NOT NULL DEFAULT 1,write_token TEXT NOT NULL,review_note TEXT NOT NULL DEFAULT '',reviewed_by TEXT REFERENCES account_users(id),reviewed_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(owner_id,request_id));
CREATE INDEX event_registrations_owner ON event_registrations(owner_id,created_at);
CREATE INDEX event_registrations_status ON event_registrations(status,created_at);
CREATE TABLE event_students (id TEXT PRIMARY KEY,registration_id TEXT NOT NULL REFERENCES event_registrations(id) ON DELETE CASCADE,position INTEGER NOT NULL,first_name TEXT NOT NULL,last_name TEXT NOT NULL,grade TEXT NOT NULL,school TEXT NOT NULL,document_id TEXT NOT NULL UNIQUE REFERENCES registration_documents(id),UNIQUE(registration_id,position));
CREATE TABLE event_registration_reviews (id TEXT PRIMARY KEY,registration_id TEXT NOT NULL REFERENCES event_registrations(id),revision INTEGER NOT NULL,reviewer_id TEXT NOT NULL REFERENCES account_users(id),status TEXT NOT NULL CHECK(status IN ('approved','changes_requested')),note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,UNIQUE(registration_id,revision));
